mapper.select:
SELECT

FROM mes_equipment_status_log
WHERE equipment_id = #{equipmentId}
ORDER BY record_time DESC

    LIMIT #{limit}

SELECT

FROM mes_equipment_status_log
WHERE equipment_id = #{equipmentId}
AND log_type = 1  

    AND record_time >= #{startTime}


    AND record_time <= #{endTime}

ORDER BY record_time DESC

SELECT
FROM mes_equipment_status_log WHERE equipment_id = #{equipmentId} AND log_type = 4 AND alarm_code IS NOT NULL ORDER BY record_time DESC
LIMIT #{limit}

SELECT
l.*,

FROM mes_equipment_status_log l
LEFT JOIN mes_equipment e ON l.equipment_id = e.equipment_id
WHERE 1=1

    AND l.equipment_id = #{query.equipmentId}


    AND e.equipment_code = #{query.equipmentCode}


    AND e.equipment_name LIKE CONCAT('%', #{query.equipmentName}, '%')


    AND l.log_type = #{query.logType}


    AND l.status = #{query.status}


    AND l.record_time >= #{query.recordTimeStart}


    AND l.record_time <= #{query.recordTimeEnd}


    AND l.recorder LIKE CONCAT('%', #{query.recorder}, '%')


    AND l.alarm_code = #{query.alarmCode}


    AND l.alarm_level = #{query.alarmLevel}


    AND l.alarm_level >= #{query.minAlarmLevel}


    AND l.alarm_level <= #{query.maxAlarmLevel}


    AND l.alarm_info LIKE CONCAT('%', #{query.alarmKeyword}, '%')


    AND l.inspection_qualified = #{query.inspectionQualified}


    AND l.inspector LIKE CONCAT('%', #{query.inspector}, '%')


    AND l.operator = #{query.operator}


    AND l.shift = #{query.shift}


    AND e.workshop = #{query.workshop}


    AND e.equipment_type = #{query.equipmentType}



    AND l.log_type = 4


    AND l.log_type = 3


    AND l.log_type = 1



    AND (
    l.alarm_info LIKE CONCAT('%', #{query.keyword}, '%')
    OR l.remark LIKE CONCAT('%', #{query.keyword}, '%')
    OR e.equipment_code LIKE CONCAT('%', #{query.keyword}, '%')
    OR e.equipment_name LIKE CONCAT('%', #{query.keyword}, '%')
    )

ORDER BY


        l.${query.sortField} ${query.sortOrder}


        l.record_time DESC

SELECT
equipment_id,
SUM(running_hours) as total_running_hours,
COUNT(*) as log_count
FROM mes_equipment_status_log
WHERE equipment_id = #{equipmentId}

    AND record_time >= #{startTime}


    AND record_time <= #{endTime}

AND log_type IN (1, 2)  
GROUP BY equipment_id

SELECT equipment_id, SUM(running_hours) as total_downtime_hours, COUNT(*) as downtime_count FROM mes_equipment_status_log WHERE equipment_id = #{equipmentId}
AND record_time >= #{startTime}
AND record_time <= #{endTime}
AND log_type = 1 AND status = 5 GROUP BY equipment_id

SELECT equipment_id, SUM(output_count) as total_output, SUM(good_count) as total_good_output, SUM(defect_count) as total_defect_output FROM mes_equipment_status_log WHERE equipment_id = #{equipmentId}
AND record_time >= #{startTime}
AND record_time <= #{endTime}
AND log_type = 5 GROUP BY equipment_id

SELECT equipment_id, SUM(energy_consumption) as total_energy_consumption, AVG(energy_consumption) as avg_energy_consumption FROM mes_equipment_status_log WHERE equipment_id = #{equipmentId}
AND record_time >= #{startTime}
AND record_time <= #{endTime}
AND log_type IN (2, 5) AND energy_consumption IS NOT NULL GROUP BY equipment_id

SELECT equipment_id,
(SUM(CASE WHEN status = 1 THEN running_hours ELSE 0 END) / NULLIF(SUM(CASE WHEN log_type IN (1,2) THEN running_hours ELSE 0 END), 0)) * 100 as availability_rate,
(SUM(CASE WHEN log_type = 5 THEN output_count ELSE 0 END) / NULLIF(SUM(CASE WHEN status = 1 THEN running_hours ELSE 0 END), 0)) as performance_rate,
(SUM(CASE WHEN log_type = 5 THEN good_count ELSE 0 END) / NULLIF(SUM(CASE WHEN log_type = 5 THEN output_count ELSE 0 END), 0)) * 100 as quality_rate FROM mes_equipment_status_log WHERE equipment_id = #{equipmentId}
AND record_time >= #{startTime}
AND record_time <= #{endTime}
GROUP BY equipment_id

mapper.delete:
DELETE FROM mes_equipment_status_log
WHERE record_time < DATE_SUB(NOW(), INTERVAL #{days} DAY)

    AND log_type = #{logType}

mapper.select:
SELECT alarm_code, alarm_info, COUNT(*) as alarm_count, MIN(record_time) as first_occurrence, MAX(record_time) as last_occurrence, GROUP_CONCAT(DISTINCT DATE(record_time) ORDER BY record_time DESC) as occurrence_dates FROM mes_equipment_status_log WHERE equipment_id = #{equipmentId} AND alarm_code IS NOT NULL
AND record_time >= #{startTime}
AND record_time <= #{endTime}
GROUP BY alarm_code, alarm_info ORDER BY alarm_count DESC

SELECT
status,
COUNT(*) as count,
SUM(running_hours) as total_hours,
(SUM(running_hours) / (SELECT SUM(running_hours) FROM mes_equipment_status_log
WHERE equipment_id = #{equipmentId}

    AND record_time >= #{startTime}


    AND record_time <= #{endTime}
)) * 100 as percentage
FROM mes_equipment_status_log
WHERE equipment_id = #{equipmentId}

    AND record_time >= #{startTime}


    AND record_time <= #{endTime}

AND log_type = 1  
GROUP BY status
ORDER BY status

SELECT DATE(record_time) as date, SUM(CASE WHEN status = 1 THEN running_hours ELSE 0 END) as running_hours, SUM(CASE WHEN status = 2 THEN running_hours ELSE 0 END) as idle_hours, SUM(CASE WHEN status = 5 THEN running_hours ELSE 0 END) as downtime_hours, SUM(output_count) as output, SUM(good_count) as good_output, SUM(energy_consumption) as energy_consumption, COUNT(DISTINCT CASE WHEN alarm_code IS NOT NULL THEN alarm_code END) as alarm_count FROM mes_equipment_status_log WHERE equipment_id = #{equipmentId}
AND record_time >= #{startTime}
AND record_time <= #{endTime}
GROUP BY DATE(record_time) ORDER BY date
